public
enum MobileMeshError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {



    case InvalidPeer
    case SessionUnavailable
    case OperationInProgress
    case CounterPersistenceFailed
    case SendFailed
    case ChatComposeFailed
    case ChatBatchMissing
    /**
     * A channel key was not exactly 32 octets.
     */
    case InvalidChannelKey
    /**
     * The MAC's channel table is full.
     */
    case ChannelCapacity
    /**
     * The conversation address was malformed, or named a channel this
     * session holds no key for.
     */
    case UnknownConversation
    /**
     * A shared location did not name a place: a non-finite or
     * out-of-range coordinate, or a precision the cell code cannot
     * carry.
     */
    case InvalidLocation
    /**
     * A management request does not fit one Node Management payload, or
     * asked for nothing at all.
     */
    case InvalidRequest
    /**
     * An addressed ask went out and nothing came back before its
     * deadline.
     */
    case NoAnswer
    /**
     * A route named something other than two-octet router hints, or more
     * of them than a frame carries.
     */
    case InvalidRoute
    /**
     * A message could not be sent again under its wire ID: its stream has
     * moved past it. It can only go again as a new message.
     */
    case ChatResendNotInPlace






    public var errorDescription: String? {
        String(reflecting: self)
    }

}

